/** Code → item lookup. */
export const NACE_21_INDEX: Record<string, NaceItem> = Object.fromEntries(
  NACE_21.map(n => [n.code, n]),
);

/** Direct children of a code (or the sections, when code is undefined). */
export const naceChildren = (code?: string): NaceItem[] =>
  NACE_21.filter(n => n.parent === code);

/** Chain of ancestors for a code, outermost (section) first. */
export const naceAncestors = (code: string): NaceItem[] => {
  const chain: NaceItem[] = [];
  let cur = NACE_21_INDEX[code]?.parent;
  while (cur) {
    const item = NACE_21_INDEX[cur];
    if (!item) break;
    chain.unshift(item);
    cur = item.parent;
  }
  return chain;
};
